@extends('layouts.app') @section('title','Notifications — AXOS') @section('content')<div class="container"><div style="display:flex;justify-content:space-between"><h1>Notifications</h1><form method="POST" action="{{route('notifications.all')}}">@csrf @method('PATCH')<button class="btn2">Mark all read</button></form></div>@forelse($notifications as $n)<div class="card" style="margin:10px 0;opacity:{{$n->read_at?'0.65':'1'}}"><p>{{$n->data['message']??'Notification'}}</p><small class="muted">{{$n->created_at->diffForHumans()}}</small>@if(!$n->read_at)<form method="POST" action="{{route('notifications.read',$n->id)}}">@csrf @method('PATCH')<button class="btn2">Mark read</button></form>@endif</div>@empty<div class="card">No notifications.</div>@endforelse{{$notifications->links()}}</div>@endsection